functions.body:
block([row, A, pivots],
    row:1,
    pivots: sort(pivots_cols),
    A:zeromatrix(m,n),
    for i thru length(pivots) do(
        piv: pivots[i],
        A[row][piv]:1,
        for j:piv+1 thru n do (
            A[row][j]:rand_with_prohib(min_val,max_val,[])
            ),
        row:row+1
        ),
     for i thru length(pivots) do(
        piv: pivots[i],
        for j:1 thru i-1 do (
            A[j][piv]:0
            )
        ),
    A)

block([L,mm,nn,r,p,st,cs,pv,tmp],L:makelist(makelist(M[i][j],j,1,length(M[1])),i,1,length(M)),mm:length(L),nn:length(L[1]),r:1,st:[],cs:[],
 for c:1 thru nn do if r<=mm then (p:0,for i:r thru mm do if p=0 and L[i][c]#0 then p:i,
  if p>0 then (if p#r then (tmp:L[r],L[r]:L[p],L[p]:tmp),pv:L[r][c],L[r]:L[r]/pv,
   for i:1 thru mm do if i#r then L[i]:L[i]-L[i][c]*L[r],
   st:endcons(apply(matrix,L),st),cs:endcons([c,p,r,pv],cs),r:r+1)),[st,cs])
